python -c "import certifi;print(certifi.where())"

New-Item -ItemType Directory -Force C:\Workspace\SoriaProblem\certs | Out-Null
$bd = Get-ChildItem Cert:\LocalMachine\Root, Cert:\CurrentUser\Root | Where-Object { $_.Subject -match 'Bitdefender' }
$lines = New-Object System.Collections.Generic.List[string]
foreach ($c in $bd) {
  $lines.Add('-----BEGIN CERTIFICATE-----')
  $lines.Add([Convert]::ToBase64String($c.RawData, 'InsertLineBreaks'))
